package com.example.lending.domain;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Objects;
import java.util.UUID;

public class Loan {

    static final int LOAN_PERIOD_DAYS = 14;
    static final long LATE_FEE_PER_DAY = 100;

    private final UUID id;
    private final UUID bookId;
    private final UUID memberId;
    private final LocalDate loanedAt;
    private final LocalDate dueAt;
    private LocalDate returnedAt;
    // 신용조회를 거치지 않은 대출은 null 이다
    private final CreditCheck creditCheck;

    private Loan(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt, LocalDate returnedAt,
                 CreditCheck creditCheck) {
        this.id = Objects.requireNonNull(id, "id");
        this.bookId = Objects.requireNonNull(bookId, "bookId");
        this.memberId = Objects.requireNonNull(memberId, "memberId");
        this.loanedAt = Objects.requireNonNull(loanedAt, "loanedAt");
        this.dueAt = Objects.requireNonNull(dueAt, "dueAt");
        if (dueAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("dueAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
        this.creditCheck = creditCheck;
    }

    // 대출 생성은 Book.loanTo를 통해서만 (대출 가능 여부 규칙을 우회하지 않도록 package-private)
    static Loan start(UUID bookId, UUID memberId, LocalDate loanedAt, CreditCheck creditCheck) {
        return new Loan(UUID.randomUUID(), bookId, memberId, loanedAt, loanedAt.plusDays(LOAN_PERIOD_DAYS), null,
                Objects.requireNonNull(creditCheck, "creditCheck"));
    }

    public static Loan reconstitute(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                                    LocalDate returnedAt, CreditCheck creditCheck) {
        return new Loan(id, bookId, memberId, loanedAt, dueAt, returnedAt, creditCheck);
    }

    public void markReturned(LocalDate returnedAt) {
        if (isReturned()) {
            throw new LoanAlreadyReturnedException(id);
        }
        Objects.requireNonNull(returnedAt, "returnedAt");
        if (returnedAt.isBefore(loanedAt)) {
            throw new IllegalArgumentException("returnedAt must not be before loanedAt");
        }
        this.returnedAt = returnedAt;
    }

    public boolean isReturned() {
        return returnedAt != null;
    }

    public boolean isOverdue(LocalDate today) {
        return today.isAfter(dueAt);
    }

    // 기한 당일 반납은 연체가 아니다. 반납 전이면 연체일은 0이다.
    public long overdueDays() {
        if (!isReturned() || !returnedAt.isAfter(dueAt)) {
            return 0;
        }
        return ChronoUnit.DAYS.between(dueAt, returnedAt);
    }

    public long lateFee() {
        return overdueDays() * LATE_FEE_PER_DAY;
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public CreditCheck getCreditCheck() {
        return creditCheck;
    }
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.domain.CreditCheck;
import com.example.lending.domain.Loan;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;
import java.time.LocalDate;
import java.util.Arrays;
import java.util.List;
import java.util.UUID;

@Entity
@Table(name = "loan")
public class LoanJpaEntity {

    @Id
    private UUID id;

    @Column(nullable = false)
    private UUID bookId;

    @Column(nullable = false)
    private UUID memberId;

    @Column(nullable = false)
    private LocalDate loanedAt;

    @Column(nullable = false)
    private LocalDate dueAt;

    private LocalDate returnedAt;

    // 신용조회 결과. 조회 없이 만들어진 대출은 null 이다
    private Boolean creditApproved;
    private Integer creditScore;
    private String creditReasonCodes;
    private Instant creditCheckedAt;
    private String creditProviderName;
    private String creditProviderVersion;

    protected LoanJpaEntity() {
    }

    private LoanJpaEntity(UUID id, UUID bookId, UUID memberId, LocalDate loanedAt, LocalDate dueAt,
                          LocalDate returnedAt, Boolean creditApproved, Integer creditScore,
                          String creditReasonCodes, Instant creditCheckedAt, String creditProviderName,
                          String creditProviderVersion) {
        this.id = id;
        this.bookId = bookId;
        this.memberId = memberId;
        this.loanedAt = loanedAt;
        this.dueAt = dueAt;
        this.returnedAt = returnedAt;
        this.creditApproved = creditApproved;
        this.creditScore = creditScore;
        this.creditReasonCodes = creditReasonCodes;
        this.creditCheckedAt = creditCheckedAt;
        this.creditProviderName = creditProviderName;
        this.creditProviderVersion = creditProviderVersion;
    }

    static LoanJpaEntity from(Loan loan) {
        CreditCheck creditCheck = loan.getCreditCheck();
        if (creditCheck == null) {
            return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                    loan.getDueAt(), loan.getReturnedAt(), null, null, null, null, null, null);
        }
        return new LoanJpaEntity(loan.getId(), loan.getBookId(), loan.getMemberId(), loan.getLoanedAt(),
                loan.getDueAt(), loan.getReturnedAt(), creditCheck.approved(), creditCheck.score(),
                String.join(",", creditCheck.reasonCodes()), creditCheck.checkedAt(),
                creditCheck.providerName(), creditCheck.providerVersion());
    }

    // 신용조회 결과 없이 읽는 경우가 있으므로 creditCheck 는 조회 결과가 있을 때만 채운다
    Loan toDomain() {
        return Loan.reconstitute(id, bookId, memberId, loanedAt, dueAt, returnedAt, toCreditCheck());
    }

    private CreditCheck toCreditCheck() {
        if (creditApproved == null) {
            return null;
        }
        return new CreditCheck(creditApproved, creditScore, toReasonCodes(), creditCheckedAt,
                creditProviderName, creditProviderVersion);
    }

    private List<String> toReasonCodes() {
        if (creditReasonCodes == null || creditReasonCodes.isEmpty()) {
            return List.of();
        }
        return Arrays.asList(creditReasonCodes.split(","));
    }

    public UUID getId() {
        return id;
    }

    public UUID getBookId() {
        return bookId;
    }

    public UUID getMemberId() {
        return memberId;
    }

    public LocalDate getLoanedAt() {
        return loanedAt;
    }

    public LocalDate getDueAt() {
        return dueAt;
    }

    public LocalDate getReturnedAt() {
        return returnedAt;
    }

    public Boolean getCreditApproved() {
        return creditApproved;
    }

    public Integer getCreditScore() {
        return creditScore;
    }

    public String getCreditReasonCodes() {
        return creditReasonCodes;
    }

    public Instant getCreditCheckedAt() {
        return creditCheckedAt;
    }

    public String getCreditProviderName() {
        return creditProviderName;
    }

    public String getCreditProviderVersion() {
        return creditProviderVersion;
    }
}
package com.example.lending.adapter.out.persistence;

import jakarta.persistence.LockModeType;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.Pageable;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Lock;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

public interface LoanJpaRepository extends JpaRepository<LoanJpaEntity, UUID> {

    long countByMemberIdAndReturnedAtIsNull(UUID memberId);

    // 도서 제목을 얻으려고 book 과 조인한다. 정렬 키가 같은 대출끼리도 페이지가 겹치지 않도록 id 로 정렬을 고정한다
    @Query(value = """
            select new com.example.lending.adapter.out.persistence.ActiveLoanRow(l.id, b.id, b.title, l.loanedAt, l.dueAt)
            from LoanJpaEntity l, BookJpaEntity b
            where b.id = l.bookId and l.memberId = :memberId and l.returnedAt is null
            order by l.loanedAt asc, l.id asc
            """,
            countQuery = """
            select count(l) from LoanJpaEntity l
            where l.memberId = :memberId and l.returnedAt is null
            """)
    Page<ActiveLoanRow> findActiveLoans(@Param("memberId") UUID memberId, Pageable pageable);

    // 반납 여부와 관계없이 전체 이력을 대출일 최신순으로 읽는다. 같은 날 대출은 id 로 순서를 고정한다
    @Query("""
            select new com.example.lending.adapter.out.persistence.LoanHistoryRow(l.id, l.bookId, l.memberId, b.title,
                    l.loanedAt, l.dueAt, l.returnedAt)
            from LoanJpaEntity l, BookJpaEntity b
            where b.id = l.bookId and l.memberId = :memberId
            order by l.loanedAt desc, l.id desc
            """)
    List<LoanHistoryRow> findLoanHistory(@Param("memberId") UUID memberId);

    // 같은 대출에 대한 동시 반납 요청을 직렬화하기 위해 트랜잭션 안에서 행 잠금을 건다
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("select l from LoanJpaEntity l where l.id = :id")
    Optional<LoanJpaEntity> findByIdForUpdate(@Param("id") UUID id);
}
package com.example.lending.adapter.out.persistence;

import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.LoadMemberLoanHistoryPort;
import com.example.lending.application.port.out.LoadMemberLoansPort;
import com.example.lending.application.port.out.LoadMemberLoansPort.MemberLoanItem;
import com.example.lending.application.port.out.LoadMemberLoansPort.MemberLoanPage;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, LoadLoanPort, LoadMemberLoansPort,
        LoadMemberLoanHistoryPort {

    private final LoanJpaRepository loanJpaRepository;

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(LoanJpaEntity.from(loan));
    }

    @Override
    public long countActiveLoansByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(LoanJpaEntity::toDomain);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findByIdForUpdate(loanId).map(LoanJpaEntity::toDomain);
    }

    @Override
    public MemberLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        Page<ActiveLoanRow> rows = loanJpaRepository.findActiveLoans(memberId, PageRequest.of(page, size));
        List<MemberLoanItem> items = rows.getContent().stream()
                .map(row -> new MemberLoanItem(row.loanId(), row.bookId(), row.title(), row.loanedAt(), row.dueAt()))
                .toList();
        return new MemberLoanPage(items, rows.getNumber(), rows.getSize(), rows.getTotalElements());
    }

    @Override
    public List<LoanHistoryEntry> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findLoanHistory(memberId).stream()
                .map(row -> new LoanHistoryEntry(row.title(), Loan.reconstitute(row.loanId(), row.bookId(),
                        row.memberId(), row.loanedAt(), row.dueAt(), row.returnedAt(), null)))
                .toList();
    }
}
