import com.example.lending.application.port.out.LoadMemberLoansPort.MemberLoanPage;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.Loan;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.Optional;
import java.util.UUID;

@Component
public class LoanPersistenceAdapter implements SaveLoanPort, LoadLoanPort, LoadMemberLoansPort,
        LoadMemberLoanHistoryPort {

    private final LoanJpaRepository loanJpaRepository;

    public LoanPersistenceAdapter(LoanJpaRepository loanJpaRepository) {
        this.loanJpaRepository = loanJpaRepository;
    }

    @Override
    public void saveLoan(Loan loan) {
        loanJpaRepository.save(LoanJpaEntity.from(loan));
    }

    @Override
    public long countActiveLoansByMemberId(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public Optional<Loan> loadLoan(UUID loanId) {
        return loanJpaRepository.findById(loanId).map(LoanJpaEntity::toDomain);
    }

    @Override
    public Optional<Loan> loadLoanForUpdate(UUID loanId) {
        return loanJpaRepository.findByIdForUpdate(loanId).map(LoanJpaEntity::toDomain);
    }

    @Override
    public MemberLoanPage loadActiveLoans(UUID memberId, int page, int size) {
        Page<ActiveLoanRow> rows = loanJpaRepository.findActiveLoans(memberId, PageRequest.of(page, size));
        List<MemberLoanItem> items = rows.getContent().stream()
                .map(row -> new MemberLoanItem(row.loanId(), row.bookId(), row.title(), row.loanedAt(), row.dueAt()))
                .toList();
        return new MemberLoanPage(items, rows.getNumber(), rows.getSize(), rows.getTotalElements());
    }

    @Override
    public List<LoanHistoryEntry> loadLoanHistory(UUID memberId) {
        return loanJpaRepository.findLoanHistory(memberId).stream()
                .map(row -> new LoanHistoryEntry(row.title(), Loan.reconstitute(row.loanId(), row.bookId(),
                        row.memberId(), row.loanedAt(), row.dueAt(), row.returnedAt(), null)))
                .toList();
    }
}
