package com.example.lending.application.service;

import com.example.lending.application.port.in.ReturnLoanUseCase;
import com.example.lending.application.port.in.ReturnLoanUseCase.ReturnLoanCommand;
import com.example.lending.application.port.out.LoadBookPort;
import com.example.lending.application.port.out.LoadLoanPort;
import com.example.lending.application.port.out.SaveAuditLogPort;
import com.example.lending.application.port.out.SaveBookPort;
import com.example.lending.application.port.out.SaveLoanPort;
import com.example.lending.domain.AuditAction;
import com.example.lending.domain.AuditLog;
import com.example.lending.domain.Book;
import com.example.lending.domain.BookNotFoundException;
import com.example.lending.domain.Loan;
import com.example.lending.domain.LoanNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDate;

@Service
@Transactional
public class ReturnLoanService implements ReturnLoanUseCase {

    private final LoadLoanPort loadLoanPort;
    private final SaveLoanPort saveLoanPort;
    private final LoadBookPort loadBookPort;
    private final SaveBookPort saveBookPort;
    private final SaveAuditLogPort saveAuditLogPort;

    public ReturnLoanService(LoadLoanPort loadLoanPort, SaveLoanPort saveLoanPort, LoadBookPort loadBookPort,
                             SaveBookPort saveBookPort, SaveAuditLogPort saveAuditLogPort) {
        this.loadLoanPort = loadLoanPort;
        this.saveLoanPort = saveLoanPort;
        this.loadBookPort = loadBookPort;
        this.saveBookPort = saveBookPort;
        this.saveAuditLogPort = saveAuditLogPort;
    }

    @Override
    public Loan returnLoan(ReturnLoanCommand command) {
        Loan loan = loadLoanPort.loadLoanForUpdate(command.loanId())
                .orElseThrow(() -> new LoanNotFoundException(command.loanId()));
        LocalDate returnedAt = command.returnedAt() != null ? command.returnedAt() : LocalDate.now();
        loan.markReturned(returnedAt);

        // 예약 줄과 반납이 겹치지 않도록 도서 행에 잠금을 건다
        Book book = loadBookPort.loadBookForUpdate(loan.getBookId())
                .orElseThrow(() -> new BookNotFoundException(loan.getBookId()));
        book.returnBook();
        saveBookPort.saveBook(book);
        saveLoanPort.saveLoan(loan);
        saveAuditLogPort.saveAuditLog(AuditLog.record(AuditAction.RETURN, loan.getId(), loan.getMemberId()));
        return loan;
    }
}
