package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMonthlyStatsUseCase;
import com.example.lending.application.port.out.LoadLoanStatsPort;
import com.example.lending.domain.Loan;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.DateTimeException;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

@Service
@Transactional(readOnly = true)
public class GetMonthlyStatsService implements GetMonthlyStatsUseCase {

    private final LoadLoanStatsPort loadLoanStatsPort;

    public GetMonthlyStatsService(LoadLoanStatsPort loadLoanStatsPort) {
        this.loadLoanStatsPort = loadLoanStatsPort;
    }

    @Override
    public MonthlyStats getMonthlyStats(int year, int month) {
        YearMonth yearMonth = toYearMonth(year, month);
        LocalDate from = yearMonth.atDay(1);
        LocalDate to = yearMonth.atEndOfMonth();

        long loanCount = loadLoanStatsPort.countLoansLoanedBetween(from, to);
        List<Loan> returnedLoans = loadLoanStatsPort.loadLoansReturnedBetween(from, to);
        long overdueCount = returnedLoans.stream()
                .filter(loan -> loan.lateFee() > 0)
                .count();
        long lateFeeTotal = returnedLoans.stream()
                .mapToLong(Loan::lateFee)
                .sum();
        return new MonthlyStats(year, month, loanCount, returnedLoans.size(), overdueCount, lateFeeTotal);
    }

    // YearMonth 은 잘못된 값에 DateTimeException 을 던지므로 입력 오류로 바꾼다
    private static YearMonth toYearMonth(int year, int month) {
        try {
            return YearMonth.of(year, month);
        } catch (DateTimeException e) {
            throw new IllegalArgumentException(e.getMessage(), e);
        }
    }
}

