package com.example.lending;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.Map;
import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

// 다른 테스트와 데이터가 섞이지 않도록 아무 테스트도 쓰지 않는 2041년 3월을 기준으로 검증한다
@SpringBootTest
@AutoConfigureMockMvc
class StatsIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void month_without_activity_returns_all_zeros() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "7"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2041))
                .andExpect(jsonPath("$.month").value(7))
                .andExpect(jsonPath("$.loanCount").value(0))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void loans_are_counted_by_loan_date_and_returns_by_return_date() throws Exception {
        String memberId = registerMember();

        // 3월 대출 3건 중 1건은 반납되지 않았고, 2월 대출 2건 중 1건은 3월에 반납되었다
        String lateInMarch = loanOn("2041-03-01", memberId);
        String onTimeInMarch = loanOn("2041-03-05", memberId);
        String activeInMarch = loanOn("2041-03-10", memberId);
        String februaryOnTime = loanOn("2041-02-25", memberId);
        String februaryVeryLate = loanOn("2041-02-01", memberId);

        returnOn(lateInMarch, "2041-03-20");       // 기한 03-15, 5일 연체 -> 500
        returnOn(onTimeInMarch, "2041-03-10");     // 기한 03-19, 정상 반납
        returnOn(februaryOnTime, "2041-03-02");    // 기한 03-11, 정상 반납
        returnOn(februaryVeryLate, "2041-03-03");  // 기한 02-15, 16일 연체 -> 1600

        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "3"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.year").value(2041))
                .andExpect(jsonPath("$.month").value(3))
                .andExpect(jsonPath("$.loanCount").value(3))
                .andExpect(jsonPath("$.returnCount").value(4))
                .andExpect(jsonPath("$.overdueCount").value(2))
                .andExpect(jsonPath("$.lateFeeTotal").value(2100));

        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.loanCount").value(2))
                .andExpect(jsonPath("$.returnCount").value(0))
                .andExpect(jsonPath("$.overdueCount").value(0))
                .andExpect(jsonPath("$.lateFeeTotal").value(0));
    }

    @Test
    void invalid_month_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041").param("month", "13"))
                .andExpect(status().isBadRequest());
    }

    @Test
    void missing_parameter_returns_400() throws Exception {
        mockMvc.perform(get("/stats/monthly").param("year", "2041"))
                .andExpect(status().isBadRequest());
    }

    private String loanOn(String loanedAt, String memberId) throws Exception {
        String bookId = registerBook();
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                        .content(objectMapper.writeValueAsString(
                                Map.of("bookId", bookId, "memberId", memberId, "loanedAt", loanedAt))))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private void returnOn(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId).contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String registerBook() throws Exception {
        String registered = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String memberId = UUID.randomUUID().toString();
        mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"memberId\":\"" + memberId + "\",\"name\":\"통계\"}"))
                .andExpect(status().isCreated());
        return memberId;
    }
}

